// Exact census of H8/M5/S<=6 cache schedules using observer-aware
// prefix L-3 matching. Sources pinned to EC49EXQ + EC49EXJ finite model.
// Build: g++ -O3 -std=c++17 SCREEN_EC49EXS.cpp -o screen_exs
// Run:   ./screen_exs EC49EXS_MATCH_TABLE.txt > EC49EXS_CENSUS.json
// The table is generated by GENERATE_EC49EXS.py by exhaustive native words.
#include <algorithm>
#include <array>
#include <cassert>
#include <fstream>
#include <iostream>
#include <map>
#include <numeric>
#include <set>
#include <string>
#include <vector>
using namespace std;
struct K{int u,v,w,ty,L; bool operator==(const K&z)const{return u==z.u&&v==z.v&&w==z.w;}};
vector<K> S[9];
vector<K> keys(int h){
 vector<K> out;
 for(int w=1;w<=(h+1)/2;w++)for(int u=0;u<=2*h+2;u++)for(int v=0;v<=h+1;v++){
  int r=u+v-h-1,f=h+1-v-2*w,g=h+1-u;
  if(min({r,f,g})>=0&&(r>=1||(r==0&&f>=1&&g>=1)))out.push_back({u,v,w,r>=1?4:2,2*(u+v+w-1)});
 }
 return out;
}
int typ(int h,const K&k){return k.u+k.v-h-1>=1?4:2;}
string ID(vector<int>hs,const K&k){
 string s;for(int h:hs)s+=to_string(h)+",";
 return s+":"+to_string(k.u)+","+to_string(k.v)+","+to_string(k.w);
}
map<string,pair<int,int>> matching; // old upper bound and observer-aware upper bound
void load_matching(const char*filename){
 ifstream in(filename);if(!in){cerr<<"cannot open matching table\n";exit(1);}
 string header;getline(in,header);assert(header.rfind("# n ",0)==0);
 int n,h1,h2,h3,u,v,w,oldm,newm;
 while(in>>n>>h1>>h2>>h3>>u>>v>>w>>oldm>>newm){
  vector<int>hs={h1,h2};if(n==3)hs.push_back(h3);
  assert(n==2||n==3);assert(is_sorted(hs.begin(),hs.end()));assert(newm<=oldm);
  K k{u,v,w,0,0};auto inserted=matching.emplace(ID(hs,k),make_pair(oldm,newm));assert(inserted.second);
 }
 assert(matching.size()==140);
}
int overlap(const K&a,const K&b){return 2*(min(a.u,b.u)+min(a.v,b.v)+min(a.w,b.w)-1);}
struct Costs{int exq,exs;};
Costs bound(const array<K,5>&ks,const array<vector<int>,5>&hs){
 int maxlen=0,M[5],Rold[5],Rnew[5],lens[5],caps[5][5]{};vector<int> breaks{1};
 for(int i=0;i<5;i++){
  lens[i]=ks[i].L;maxlen=max(maxlen,lens[i]);
  M[i]=0;for(int h:hs[i])M[i]+=typ(h,ks[i]);
  int oldm=0,newm=0;
  if(hs[i].size()>1){
   auto found=matching.find(ID(hs[i],ks[i]));
   if(found==matching.end()){cerr<<"missing match for key/group "<<ID(hs[i],ks[i])<<"\n";exit(3);}
   oldm=found->second.first;newm=found->second.second;
  }
  Rold[i]=M[i]-oldm;Rnew[i]=M[i]-newm;
  breaks.push_back(max(1,lens[i]-3));breaks.push_back(lens[i]-2);breaks.push_back(lens[i]+1);
  for(int j=0;j<i;j++){
   caps[j][i]=caps[i][j]=overlap(ks[i],ks[j]);breaks.push_back(caps[i][j]+1);
  }
 }
 breaks.push_back(maxlen+1);
 sort(breaks.begin(),breaks.end());breaks.erase(unique(breaks.begin(),breaks.end()),breaks.end());
 int prev=0,ref=0;
 for(size_t t=0;t+1<breaks.size();t++){
  int d=breaks[t],width=breaks[t+1]-d;
  if(d>maxlen||width<=0)continue;
  int q[5],r[5];
  for(int i=0;i<5;i++){
   q[i]=d>lens[i]?0:d>=lens[i]-2?M[i]:d==lens[i]-3?Rold[i]:1;
   r[i]=d>lens[i]?0:d>=lens[i]-2?M[i]:d==lens[i]-3?Rnew[i]:1;
  }
  int pbest=0,rbest=0;
  for(int mask=1;mask<32;mask++){
   bool possible=true;int a=0,b=0;
   for(int i=0;i<5&&possible;i++)if(mask&(1<<i)){
    a+=q[i];b+=r[i];
    for(int j=i+1;j<5;j++)if((mask&(1<<j))&&caps[i][j]>=d){possible=false;break;}
   }
   if(possible){pbest=max(pbest,a);rbest=max(rbest,b);}
  }
  prev+=width*pbest;ref+=width*rbest;
 }
 assert(ref>=prev);
 return {prev,ref};
}
struct Summary{
 long long total=0,prev_survive=0,ref_survive=0,prev_eq80=0,ref_eq80=0;
 int minnew=9999,maxnew=0;
 map<int,long long> hist;
};
void append(Summary&x,Costs a){
 x.total++;x.prev_survive+=(a.exq<80);x.ref_survive+=(a.exs<80);
 x.prev_eq80+=(a.exq<=80);x.ref_eq80+=(a.exs<=80);
 x.minnew=min(x.minnew,a.exs);x.maxnew=max(x.maxnew,a.exs);x.hist[a.exs]++;
}
void merge(Summary&dest,const Summary&src){
 dest.total+=src.total;dest.prev_survive+=src.prev_survive;dest.ref_survive+=src.ref_survive;
 dest.prev_eq80+=src.prev_eq80;dest.ref_eq80+=src.ref_eq80;
 dest.minnew=min(dest.minnew,src.minnew);dest.maxnew=max(dest.maxnew,src.maxnew);
 for(auto [k,v]:src.hist)dest.hist[k]+=v;
}
void dump(const Summary&x){
 cout<<"{\"total\":"<<x.total<<",\"EXQ_survivors_lt80\":"<<x.prev_survive
     <<",\"EXS_survivors_lt80\":"<<x.ref_survive
     <<",\"new_excluded_lt80\":"<<x.prev_survive-x.ref_survive
     <<",\"EXQ_survivors_le80\":"<<x.prev_eq80
     <<",\"EXS_survivors_le80\":"<<x.ref_eq80
     <<",\"min_EXS_bound\":"<<x.minnew<<",\"max_EXS_bound\":"<<x.maxnew<<",\"hist\":{";
 bool first=true;for(auto [k,n]:x.hist){if(!first)cout<<",";first=false;cout<<"\""<<k<<"\":"<<n;}cout<<"}}";
}
int main(int argc,char**argv){
 if(argc<2){cerr<<"need matching table\n";return 2;}
 load_matching(argv[1]);
 for(int h=2;h<=8;h++)S[h]=keys(h);
 for(int h=2;h<=8;h++){int exp[]={1,4,9,17,28,43,62};assert(int(S[h].size())==exp[h-2]);}
 Summary triple,doub;
 ofstream survivors("EC49EXS_TRIPLE_CANDIDATES.tsv");
 survivors<<"# exs_lb exq_lb triple_h1 triple_h2 triple_h3 k0u k0v k0w k1u k1v k1w k2u k2v k2w k3u k3v k3w k4u k4v k4w\n";
 cout<<"{\"status\":\"PASS\",\"model\":\"H8_M5_S6\",\"triple_skeletons\":[";bool first=true;
 for(int a=2;a<=8;a++)for(int b=a+1;b<=8;b++)for(int c=b+1;c<=8;c++){
  vector<int>rem;for(int h=2;h<=8;h++)if(h!=a&&h!=b&&h!=c)rem.push_back(h);
  Summary group;
  for(auto k:S[a]){
   if(find(S[b].begin(),S[b].end(),k)==S[b].end()||find(S[c].begin(),S[c].end(),k)==S[c].end())continue;
   for(auto x:S[rem[0]])if(!(x==k))for(auto y:S[rem[1]])if(!(y==k)&&!(y==x))
    for(auto z:S[rem[2]])if(!(z==k)&&!(z==x)&&!(z==y))for(auto w:S[rem[3]])
     if(!(w==k)&&!(w==x)&&!(w==y)&&!(w==z)){
      array<K,5>ks={k,x,y,z,w};array<vector<int>,5>hs={vector<int>{a,b,c},vector<int>{rem[0]},vector<int>{rem[1]},vector<int>{rem[2]},vector<int>{rem[3]}};
      auto costs=bound(ks,hs);append(group,costs);
      if(costs.exs<80){survivors<<costs.exs<<" "<<costs.exq<<" "<<a<<" "<<b<<" "<<c;for(auto m:ks)survivors<<" "<<m.u<<" "<<m.v<<" "<<m.w;survivors<<"\n";}
     }
  }
  if(group.total){if(!first)cout<<",";first=false;cout<<"{\"windows\":["<<a<<","<<b<<","<<c<<"],\"stats\":";dump(group);cout<<"}";merge(triple,group);}
 }
 cout<<"],\"double_skeletons\":[";first=true;
 for(int a=2;a<=8;a++)for(int b=a+1;b<=8;b++)for(int c=a+1;c<=8;c++)if(c!=b)for(int d=c+1;d<=8;d++)if(d!=b){
  vector<int>rem;for(int h=2;h<=8;h++)if(h!=a&&h!=b&&h!=c&&h!=d)rem.push_back(h);
  if(rem.size()!=3)continue;
  Summary group;
  for(auto ka:S[a])if(find(S[b].begin(),S[b].end(),ka)!=S[b].end())for(auto kb:S[c])
   if(!(ka==kb)&&find(S[d].begin(),S[d].end(),kb)!=S[d].end()){
    for(auto x:S[rem[0]])if(!(x==ka)&&!(x==kb))for(auto y:S[rem[1]])if(!(y==ka)&&!(y==kb)&&!(y==x))
     for(auto z:S[rem[2]])if(!(z==ka)&&!(z==kb)&&!(z==x)&&!(z==y)){
      array<K,5>ks={ka,kb,x,y,z};array<vector<int>,5>hs={vector<int>{a,b},vector<int>{c,d},vector<int>{rem[0]},vector<int>{rem[1]},vector<int>{rem[2]}};
      append(group,bound(ks,hs));
     }
   }
  if(group.total){if(!first)cout<<",";first=false;cout<<"{\"pairs\":[["<<a<<","<<b<<"],["<<c<<","<<d<<"]],\"stats\":";dump(group);cout<<"}";merge(doub,group);}
 }
 cout<<"],\"triple\":";dump(triple);cout<<",\"double\":";dump(doub);Summary all;merge(all,triple);merge(all,doub);cout<<",\"all\":";dump(all);cout<<"}\n";
 assert(triple.total==123147&&doub.total==1866362);
 assert(triple.prev_survive==946&&doub.prev_survive==63665);
}
